values
  ('9c2d304d-8053-4448-8e1f-f700c82e8e33', 'zh-tw', 'smooth-smooth-challenge', '滑溜滑溜挑戰', '法國編舞師卡尼一邊背誦韓語形容詞一邊即興跳舞,意外掀起迷因熱潮。', '2025年10月29日,YouTube綜藝節目《尋找卡尼》第20集中,卡尼反覆唸著「滑溜滑溜(매끈매끈하다)」、「平坦平坦(푱푱하다)」等韓語形容詞,一邊即興跳舞的畫面引發熱議。隨後「幸福披薩麵包」的混音影片爆紅,SHINee Key、TWS、Hearts2Hearts、ZEROBASEONE等偶像也接連跟跳,又正值韓國大學修學能力測驗前夕,因此還被戲稱為「修能禁播曲」。', 'YouTube綜藝節目《尋找卡尼》第20集中背誦形容詞的橋段', '適合作為具有洗腦魔力的舞蹈挑戰案例來介紹', null, array['매끈매끈하다 챌린지', '滑溜滑溜的', '尋找卡尼', '修能禁播曲(2025)']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('c4647c65-bf96-4465-b0df-c9772cb03f07', 'zh-tw', 'park-ji-sung-two-hearts', '朴智星「兩顆心臟」', '朴智星以驚人的跑動量贏得的代表性綽號。', '朴智星效力曼聯期間,全場比賽都能維持驚人跑動量、從不喊累,因此獲得「兩顆心臟」的綽號。英國當地媒體也曾以「三個肺(Three-Lung Park)」來形容他的體能。他的每分鐘心跳數僅約40下,常被拿來作為長期鍛鍊出的運動員心臟的典型範例介紹。', '2000年代中期效力曼聯時期的表現奠定此稱號', '用來形容朴智星卓越跑動量與體能時使用的代表性綽號。', null, array['박지성 두 개의 심장', 'Three-Lung Park', '兩個心臟']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('8b03db9e-2152-4fdb-a21c-77398d5c998f', 'zh-tw', 'ongamenet-starleague-launch', 'OnGameNet星際聯賽創立', '1999~2000年韓國電競職業聯賽文化的起點。', '以1999年「99 PKO」為濫觴,自2000年「Freechal盃」起正式採用「星際聯賽」名稱的OnGameNet星際聯賽,引進開放式攝影棚與觀眾席,成為韓國電競觀賽文化普及化的起點。', '韓國電競聯賽文化源於1999年「99 PKO」大賽,2000年Hanaro通信盃Tooniverse星際聯賽起首次使用「스타리그(星際聯賽)」這個名稱。受該賽事人氣帶動,2000年7月24日在黃亨俊的提議下,遊戲專門頻道OnGameNet開台,從幾名約聘人員在倉庫房間起步的節目,成長為約80人規模的專業電視台。同一時期的2000年2月,在第21世紀職業電競協會(現韓國電子競技協會)成立典禮上,文化觀光部長官提及「電子競技」一詞,使這個說法開始在社會上普遍使用。', '可作為韓國電競產業起點來引用介紹', null, array['온게임넷 스타리그 출범', '星際聯賽', '99 PKO']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('111277eb-652c-4e7b-a474-8be535e21b1a', 'zh-tw', 'memory-of-a-sketch', '「記憶的習作」', '1994年展覽會(金東律)發表、長年受喜愛的抒情經典歌曲。', '1993年大學歌謠祭大賞出身的二人組合展覽會,於1994年發表的「記憶的習作」,在當時以舞曲、雷鬼為主流的樂壇中,以抒情的敘事曲風擄獲大眾情感,之後更因收錄於電影《建築學概論》而再度廣受喜愛。', '金東律與徐東旭在1993年12月以二人組合「展覽會」參加MBC大學歌謠祭,獲得大賞與特別獎。翌年1994年,發表由申海澈、金亨錫等人參與製作的首張專輯《Exhibition》,其中第一首歌曲便是「記憶的習作」。作詞、作曲、編曲皆由金東律一手包辦,其細膩的旋律自發行當時起便深受喜愛。2012年上映的電影《建築學概論》採用此曲後,再度引發大眾高度關注,音源排行榜逆勢回升,此後跨越世代成為韓國抒情曲的代表作。', '談論1990年代經典抒情曲時可作為代表案例提及', null, array['기억의 습작', '展覽會 記憶的習作']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('da72423d-7a4c-4f54-9e40-4eb18ea6d1bf', 'zh-tw', 'pick-me-syndrome', '「나야 나(PICK ME)」旋風', 'Produce 101 Season 2主題曲掀起的全民選秀熱潮。', '2017年4月至6月播出的Mnet《Produce 101 Season 2》主題曲「나야 나(PICK ME)」,隨著練習生的整齊舞步,在上半年掀起橫掃歌謠、影視圈的旋風。由該節目誕生的團體Wanna One於2017年8月出道後爆紅,這首歌與舞蹈也成為各類綜藝、活動中常見的模仿橋段。', 'Mnet《Produce 101 Season 2》主題曲(2017年)', '作為選秀節目旋風與團體舞模仿題材時提及', null, array['나야 나(PICK ME) 신드롬', 'Wanna One 나야나', '國民練習生 나야나']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
