values
  ('47150dcf-062e-422a-b52e-71913716e2ac', 'zh-tw', 'tastes-like-persimmon-so-i-thought-it-was-persimmon', '「因為有柿子味,所以我想那是柿子」', '2003年電視劇《大長今》中年幼長今以循環論證回答問題的流行語。', 'MBC電視劇《大長今》裡,年幼的長今將肉的味道形容為「柿子味」,面對鄭尚宮追問理由,她給出的答案陷入循環論證,這段情節引發熱議,一度流行到只要打開電視就能看到相關模仿橋段。', '2003年9月29日MBC《大長今》第5集播出的台詞。', '用來調侃邏輯前後不通的回答時引用', '無', array['홍시맛이 나서 홍시라 생각했는데', '홍시맛이 나서 홍시라 생각한 것이온데']::text[], '[{"text": "所以我就問你為什麼會這樣嘛~因為有柿子味,所以我想那是柿子(笑)", "situation": "聊天訊息"}, {"text": "這個回答根本是循環論證style", "situation": "社群留言"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
