values
  ('436ddcf5-5521-49ad-9a1c-32fb14ce0393', 'zh-tw', 'lee-malnyeon-series', '「李末年系列」', '出身DC Inside的漫畫家李末年的無厘頭網路漫畫,2009年出道作。', '李末年原本以業餘漫畫家身分活躍於DC Inside,以《燃燒的巴士》等作品受到矚目後,於2009年正式以網路漫畫《李末年系列》出道。荒誕不經、不顧邏輯連貫性的劇情發展加上獨特的無厘頭風格,讓他爆紅,並成為無厘頭網路漫畫類型的代表人物。', '歷經在DC Inside連載業餘漫畫的活動後,正式以網路漫畫出道', '提及無厘頭網路漫畫始祖案例時使用', null, array['이말년 씨리즈', '이말년씨리즈']::text[], '[{"text": "這個劇情發展根本是李末年系列等級的無厘頭", "situation": "聊天訊息"}, {"text": "無厘頭網路漫畫的始祖就是李末年吧", "situation": "社群留言"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('1849c6f7-e13a-49a1-89a6-a13c87ec42d5', 'zh-tw', 'choi-dong-won-sun-dong-yol-rivalry', '崔東原-宣銅烈「鐵臂」對決', '1987年投滿15局、以和局收場的KBO史上最強投手對決。', '1987年5月16日在釜山社稷球場,樂天崔東原與海太宣銅烈分別投出209球、232球,兩人纏鬥至延長15局仍未分勝負,以2比2和局作收。兩人先前也曾兩度先發交手,各贏一場。2022年KBO聯盟40週年「40大傳奇球星」票選中,宣銅烈奪得第一、崔東原位居第二,這場對決再度被人津津樂道。', '1987年5月16日樂天-海太比賽,2022年KBO 40週年傳奇球星票選再度被提起', '談論史上最強投手對決時引用的KBO傳奇故事', null, array['최동원-선동열 무쇠팔 라이벌전', '최동원 무쇠팔', '선동열-최동원 무승부']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('47a82b00-1c73-4829-ba79-3c6b2ac305be', 'zh-tw', 'pc-tongsin-modem-connect-sound', 'PC通訊撥接數據機連線音', '象徵1990年代PC通訊、早期網路的撥接數據機連線音。', '1990年代連上Hitel、Nownuri等PC通訊服務時發出的「嗶哩哩~ 唰———」獨特撥接數據機連線音,對那個世代的網路使用者而言,是喚起強烈懷舊情感的象徵性聲音。當時只要有人接起電話,連線就會中斷,也是常見的情況。', '指1990年代初中期連上Hitel、天里眼、Nownuri等PC通訊服務時,透過電話線傳來的「嗶~ 唰唰~ 咻」撥接數據機訊號音。這是為了透過電話線路傳輸數位訊號而進行「握手」程序時產生的聲音,當時使用者之間常戲稱為「馬桶沖水聲」或「尖叫聲」,並成為一種迷因流傳。隨著寬頻網路普及,這種聲音逐漸消失,但取樣此聲音製作的音源或YouTube懷舊影片仍持續產出,成為喚起1980~90年代學生世代懷舊情懷的文化符號。', '談論PC通訊時代的懷舊情懷時,可模仿這個聲音來回憶', null, array['PC통신 모뎀 접속음', '모뎀 접속 소리', '撥接連線音']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('9d430343-4454-4433-a0f8-ca4f27395272', 'zh-tw', 'sky-castle-sseuaengnim', '《SKY Castle》「賜~陰~您」', '電視劇《SKY Castle》中演員廉晶雅的「老師」發音造就的流行語。', '2018年播出的JTBC電視劇《SKY Castle》中,演員廉晶雅飾演的韓瑞珍向升學顧問金珠英(金瑞亨飾)苦苦哀求時,把「선생님(老師)」念成類似「쓰앵님」的獨特發音,這一幕引發熱議。此外劇中「아갈머리」、「金字塔」等台詞也接連成為流行語,引發各種模仿與配音秀。', 'JTBC電視劇《SKY Castle》韓瑞珍(廉晶雅飾)台詞(2018年)', '用來模仿苦苦懇求某人的情境時使用', null, array['SKY 캐슬 쓰앵님', '아갈머리', '혜나는 누가 죽였나요']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('1f6a0eef-6fe0-4508-a3ab-8abe3ced086a', 'zh-tw', 'hiddink-still-hungry', '希丁克「我依然感到飢餓」', '2002年世界盃16強晉級後,希丁克教練展現謙遜的名言。', '2002年韓日世界盃,韓國隊史上首次晉級16強,對於部分球員可能就此滿足的情況,主教練戈斯·希丁克留下這句話。這句話傳達出朝更大目標邁進、切勿自滿的訊息,此後在各領域被廣泛引用,用以表達「不滿足現狀、持續前進」之意。', '2002年韓日世界盃國家代表隊主教練戈斯·希丁克受訪發言', '達成目標後強調謙遜、持續精進時引用', null, array['히딩크 "나는 아직 배가 고프다"', '아직 배고프다', '希丁克語錄']::text[], '[{"text": "雖然達成目標了,但我依然感到飢餓", "situation": "聊天訊息"}, {"text": "這個心態完全是希丁克式的", "situation": "社群留言"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('2c7e2c44-0937-47f3-ade4-af273ce4a49e', 'zh-tw', 'jeong-il-young-speaking-style-meme', '鄭日永老師「說話術」迷因', '出演Chimchakman直播的仁荷大學法語講師,其獨特應對方式成為迷因的案例。', '仁荷大學法語講師鄭日永在2024年巴黎奧運期間出演Chimchakman的直播節目,以獨特的說話方式講解「沒買地鐵票被抓到時」、「在法國遭受不當對待時」等情境的應對方法,引發熱議。「우리는 XX하는 고객이에요(我們是XX的顧客)」、「빠뜨롱 나오라 그래!(叫老闆出來!)」等說法在觀眾之間被套用到各種情境,成為迷因。', '2024年巴黎奧運期間Chimchakman YouTube直播出演片段', '用來表現理直氣壯面對不當對待的情境時引用', '曾出現迷因被誤傳、與事實不符內容(如兵役相關)擴散的案例,並曾有媒體發布更正報導', array['정일영 선생님 화법 밈', '鄭日永老師']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('b4354c93-bfd9-4fc3-b24b-d5e1f944b3f0', 'zh-tw', 'balletcore', '芭蕾芯風(Balletcore)', '將芭蕾服輪廓融入日常穿搭的TikTok發跡時尚美學。', '將緊身連身衣、圍裹裙、腿套、芭蕾平底鞋等芭蕾服元素以休閒方式混搭的風格。透過TikTok、Instagram上「balletcore」標籤擴散,特色是緞帶裝飾與粉彩色調的搭配。在韓國則因Red Velvet《Feel My Rhythm》、NewJeans寫真等作品而廣為人知。', '2020年代初期在TikTok、Instagram上以「芭蕾(ballet)」與「normcore(基本款風格)」合成命名,2022年下半年隨Red Velvet回歸活動,韓國搜尋量也隨之暴增。', '介紹以芭蕾平底鞋、腿套等單品搭配出的優雅造型時使用', null, array['발레코어', '발레코어룩', 'balletcore']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('7e246da6-a151-4445-bc0d-dd88b18cfc6b', 'zh-tw', 'sorry-for-being-cute', '「可愛到抱歉(귀여워서 미안해)」', '隨日本組合HoneyWorks歌曲做出飛吻、摸臉頰動作的舞蹈挑戰。', '日本創作組合HoneyWorks的角色歌曲於2022年11月公開MV後,隨歌詞做出飛吻或如道歉般摸臉頰動作的舞蹈挑戰在TikTok上大為流行。2022年8月同人版本率先流傳並累積人氣,同年12月起K-pop偶像成員也陸續上傳舞蹈影片,使其熱度擴散至韓國內外。', '日本組合HoneyWorks歌曲「귀여워서 미안해(可愛くてごめん)」MV公開(2022年11月)', '作為任何人都能輕鬆跟跳的可愛風短版舞蹈挑戰時使用', null, array['귀여워서 미안해', '可愛くてごめん']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
