values
  ('dc46243d-f704-4519-ba01-bca3819b8be4', 'zh-tw', 'be-the-reds-tshirt', '「Be the Reds」T恤', '成為2002年世界盃全民制服的紅色「Be the Reds」T恤。', '紅魔啦啦隊自製標語「Be the Reds!」印在紅色T恤上,2002年5月上市後短短一個月內熱賣數十萬件,成為全民都在穿的「國民制服」。此後也因設計著作權訴訟而再度引發話題。', '紅魔官方啦啦隊周邊,2002年上市,設計師朴永哲繪製', '可作為象徵2002年世界盃熱潮的周邊商品提及', null, array['Be the Reds 티셔츠', '비더레즈', '붉은악마 티셔츠']::text[], '[{"text": "這次應援大家一起穿Be the Reds T恤吧", "situation": "聊天訊息"}, {"text": "那個年代真的是國民制服呢", "situation": "社群留言"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
